<template>
  <div class="home-container">
    <NavBar />
    
    <div class="main-content">
      <!-- 搜索和筛选区 -->
      <div class="filter-section">
        <el-input
          v-model="searchQuery"
          placeholder="搜索商品..."
          class="search-input"
          :prefix-icon="Search"
          clearable
        >
          <template #append>
            <el-button :icon="Search" />
          </template>
        </el-input>
        
        <div class="category-tags">
          <el-tag 
            v-for="cat in categories" 
            :key="cat" 
            :effect="selectedCategory === cat ? 'dark' : 'plain'"
            class="category-tag"
            @click="selectedCategory = cat"
          >
            {{ cat }}
          </el-tag>
        </div>
      </div>

      <!-- 商品列表区 -->
      <div class="product-grid">
        <el-card 
          v-for="item in products" 
          :key="item.id" 
          class="product-card" 
          :body-style="{ padding: '0px' }"
          shadow="hover"
          @click="goToDetail(item.id)"
        >
          <div class="image-placeholder">
            <img v-if="item.image" :src="item.image" class="product-image"/>
            <div v-else class="no-image">暂无图片</div>
          </div>
          <div class="product-info">
            <h3 class="product-title">{{ item.title }}</h3>
            <div class="product-price">¥ {{ item.price }}</div>
            <div class="product-meta">
              <span class="seller-name">{{ item.seller }}</span>
              <span class="publish-time">{{ item.time }}</span>
            </div>
          </div>
        </el-card>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive } from 'vue'
import { useRouter } from 'vue-router'
import NavBar from '@/components/NavBar.vue'
import { Search } from '@element-plus/icons-vue'

const router = useRouter()
const searchQuery = ref('')
const selectedCategory = ref('全部')

const categories = ['全部', '书籍教材', '电子数码', '生活用品', '美妆护肤', '运动器材', '其他']

// 模拟商品数据
const products = reactive([
  { id: 1, title: '二手高等数学教材', price: 15.00, seller: '张三', time: '1小时前', image: '' },
  { id: 2, title: '罗技无线鼠标', price: 45.00, seller: '李四', time: '2小时前', image: '' },
  { id: 3, title: '宜家台灯', price: 30.00, seller: '王五', time: '5小时前', image: '' },
  { id: 4, title: '考研英语资料', price: 20.00, seller: '赵六', time: '1天前', image: '' },
  { id: 5, title: '小米手环', price: 80.00, seller: '钱七', time: '2天前', image: '' },
  { id: 6, title: '自行车', price: 200.00, seller: '孙八', time: '3天前', image: '' },
])

const goToDetail = (id) => {
  router.push(`/product/${id}`)
}
</script>

<style scoped>
.home-container {
  min-height: 100vh;
  background-color: #f5f7fa;
}

.main-content {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

.filter-section {
  margin-bottom: 30px;
  background: #fff;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0 2px 12px 0 rgba(0,0,0,0.05);
}

.search-input {
  max-width: 500px;
  margin-bottom: 20px;
}

.category-tags {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.category-tag {
  cursor: pointer;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.product-card {
  transition: transform 0.3s;
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-5px);
}

.image-placeholder {
  height: 200px;
  background-color: #e9e9eb;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.product-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.no-image {
  color: #909399;
}

.product-info {
  padding: 14px;
}

.product-title {
  margin: 0 0 10px;
  font-size: 16px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.product-price {
  color: #f56c6c;
  font-size: 18px;
  font-weight: bold;
  margin-bottom: 10px;
}

.product-meta {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: #909399;
}
</style>
