<template>
  <el-menu
    :default-active="activeIndex"
    class="el-menu-demo"
    mode="horizontal"
    :ellipsis="false"
    router
  >
    <el-menu-item index="/">
      <!-- <img style="width: 40px; margin-right: 10px" src="@/assets/logo.png" alt="logo" /> -->
      <span style="font-weight: bold; font-size: 18px;">校园交易平台</span>
    </el-menu-item>
    
    <div class="flex-grow" />

    <el-menu-item index="/">首页</el-menu-item>
    <el-menu-item index="/publish">发布商品</el-menu-item>
    
    <el-sub-menu index="user">
      <template #title>
        <div class="user-info">
          <el-avatar :size="30" :src="userInfo.avatar || 'https://cube.elemecdn.com/3/7c/3ea6beec64369c2642b92c6726f1epng.png'" />
          <span style="margin-left: 8px">{{ userInfo.nickname || userInfo.username }}</span>
        </div>
      </template>
      <el-menu-item index="/profile">个人中心</el-menu-item>
      <el-menu-item index="/my-items">我的发布</el-menu-item>
      <el-menu-item @click="handleLogout">退出登录</el-menu-item>
    </el-sub-menu>
  </el-menu>
</template>

<script setup>
import { ref, computed } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { useStore } from 'vuex'
import { ElMessage } from 'element-plus'

const router = useRouter()
const route = useRoute()
const store = useStore()

const activeIndex = computed(() => route.path)

const userInfo = computed(() => store.getters.userInfo)

const handleLogout = async () => {
  await store.dispatch('logout')
  ElMessage.success('退出成功')
  router.push('/login')
}
</script>

<style scoped>
.flex-grow {
  flex-grow: 1;
}
.user-info {
  display: flex;
  align-items: center;
}
</style>
